local k={143,165,89,127,233,35,132,237,144,60,170,119,36,7,151,36,117,84,80,170,189,206,68,13,95,52,185,166,101,3,110,120}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
